static void mall_destroy_hw_filter ( struct tcf_proto * tp , struct cls_mall_head * head , unsigned long cookie ) { struct net_device * dev = tp -> q -> dev_queue -> dev ; struct tc_to_netdev offload ; offload . type = TC_SETUP_MATCHALL ; offload . cls_mall = & mall_offload ; offload . cls_mall -> command = TC_CLSMATCHALL_DESTROY ; offload . cls_mall -> exts = NULL ; offload . cls_mall -> cookie = cookie ; dev -> netdev_ops -> ndo_setup_tc ( dev , tp -> q -> handle , tp -> protocol , & offload ) ; } 